declarations.type:
∀ {n : ℕ} {G : SimpleGraph (Fin n)} {dartCount : ℕ} {tail : Fin dartCount → Fin n}
  {reverse : Equiv.Perm (Fin dartCount)} {reverse_involution : ∀ (d : Fin dartCount), reverse (reverse d) = d}
  {reverse_fixedpoint_free : ∀ (d : Fin dartCount), reverse d ≠ d}
  {dart_adjacent : ∀ (d : Fin dartCount), G.Adj (tail d) (tail (reverse d))}
  {dart_injective : Function.Injective fun d => (tail d, tail (reverse d))}
  {dart_surjective : ∀ (u v : Fin n), G.Adj u v → ∃ d, tail d = u ∧ tail (reverse d) = v} {connected : G.Connected}
  {vertex_nonempty : ∀ (v : Fin n), ∃ d, tail d = v} {rotate : Equiv.Perm (Fin dartCount)}
  {rotate_tail : ∀ (d : Fin dartCount), tail (rotate d) = tail d}
  {vertex_cyclic : ∀ (d e : Fin dartCount), tail d = tail e → rotate.SameCycle d e} {dartCount_1 : ℕ}
  {tail_1 : Fin dartCount_1 → Fin n} {reverse_1 : Equiv.Perm (Fin dartCount_1)}
  {reverse_involution_1 : ∀ (d : Fin dartCount_1), reverse_1 (reverse_1 d) = d}
  {reverse_fixedpoint_free_1 : ∀ (d : Fin dartCount_1), reverse_1 d ≠ d}
  {dart_adjacent_1 : ∀ (d : Fin dartCount_1), G.Adj (tail_1 d) (tail_1 (reverse_1 d))}
  {dart_injective_1 : Function.Injective fun d => (tail_1 d, tail_1 (reverse_1 d))}
  {dart_surjective_1 : ∀ (u v : Fin n), G.Adj u v → ∃ d, tail_1 d = u ∧ tail_1 (reverse_1 d) = v}
  {connected_1 : G.Connected} {vertex_nonempty_1 : ∀ (v : Fin n), ∃ d, tail_1 d = v}
  {rotate_1 : Equiv.Perm (Fin dartCount_1)} {rotate_tail_1 : ∀ (d : Fin dartCount_1), tail_1 (rotate_1 d) = tail_1 d}
  {vertex_cyclic_1 : ∀ (d e : Fin dartCount_1), tail_1 d = tail_1 e → rotate_1.SameCycle d e},
  { dartCount := dartCount, tail := tail, reverse := reverse, reverse_involution := reverse_involution,
        reverse_fixedpoint_free := reverse_fixedpoint_free, dart_adjacent := dart_adjacent,
        dart_injective := dart_injective, dart_surjective := dart_surjective, connected := connected,
        vertex_nonempty := vertex_nonempty, rotate := rotate, rotate_tail := rotate_tail,
        vertex_cyclic := vertex_cyclic } =
      { dartCount := dartCount_1, tail := tail_1, reverse := reverse_1, reverse_involution := reverse_involution_1,
        reverse_fixedpoint_free := reverse_fixedpoint_free_1, dart_adjacent := dart_adjacent_1,
        dart_injective := dart_injective_1, dart_surjective := dart_surjective_1, connected := connected_1,
        vertex_nonempty := vertex_nonempty_1, rotate := rotate_1, rotate_tail := rotate_tail_1,
        vertex_cyclic := vertex_cyclic_1 } →
    dartCount = dartCount_1 ∧ HEq tail tail_1 ∧ HEq reverse reverse_1 ∧ HEq rotate rotate_1

∀ {V : Type u_1} {graph : SimpleGraph V} {adjacency : Matrix V V ℝ}
  {symmetric : ∀ (i j : V), adjacency i j = adjacency j i}
  {edge_sign : ∀ (i j : V), graph.Adj i j → adjacency i j = 1 ∨ adjacency i j = -1}
  {nonedge_zero : ∀ (i j : V), ¬graph.Adj i j → adjacency i j = 0} {graph_1 : SimpleGraph V}
  {adjacency_1 : Matrix V V ℝ} {symmetric_1 : ∀ (i j : V), adjacency_1 i j = adjacency_1 j i}
  {edge_sign_1 : ∀ (i j : V), graph_1.Adj i j → adjacency_1 i j = 1 ∨ adjacency_1 i j = -1}
  {nonedge_zero_1 : ∀ (i j : V), ¬graph_1.Adj i j → adjacency_1 i j = 0},
  { graph := graph, adjacency := adjacency, symmetric := symmetric, edge_sign := edge_sign,
        nonedge_zero := nonedge_zero } =
      { graph := graph_1, adjacency := adjacency_1, symmetric := symmetric_1, edge_sign := edge_sign_1,
        nonedge_zero := nonedge_zero_1 } →
    graph = graph_1 ∧ adjacency = adjacency_1
